private static function roundToDigits(float $number, int $digits, bool $awayFromZero): float
{
    if ($number == 0.0) {
        return 0.0;
    }

    $negative = $number < 0.0;
    $absolute = abs($number);
    $integerDigits = strlen((string) (int) $absolute);
    $decimals = max(0, PHP_FLOAT_DIG - $integerDigits);
    $valueString = sprintf('%.' . $decimals . 'F', $absolute);
    if (!str_contains($valueString, '.')) {
        $valueString .= '.';
    }
    [$integerPart, $fractionPart] = explode('.', $valueString, 2);

    if ($digits >= 0) {
        $keptFraction = str_pad(substr($fractionPart, 0, $digits), $digits, '0');
        $remainder = trim(substr($fractionPart, $digits), '0') !== '';
        $resultDigits = $integerPart . $keptFraction;
        if ($awayFromZero && $remainder) {
            $resultDigits = self::incrementDigitString($resultDigits);
        }
        $resultString = ($digits === 0)
            ? $resultDigits
            : substr($resultDigits, 0, -$digits) . '.' . substr($resultDigits, -$digits);
    } else {
        $shift = -$digits;
        $integerLength = strlen($integerPart);
        if ($integerLength > $shift) {
            $keptInteger = substr($integerPart, 0, $integerLength - $shift);
            $removed = substr($integerPart, $integerLength - $shift);
        } else {
            $keptInteger = '';
            $removed = $integerPart;
        }
        $remainder = trim($removed . $fractionPart, '0') !== '';
        if ($keptInteger === '') {
            $keptInteger = '0';
        }
        if ($awayFromZero && $remainder) {
            $keptInteger = self::incrementDigitString($keptInteger);
        }
        $resultString = $keptInteger . str_repeat('0', $shift);
    }

    $result = (float) $resultString;

    return $negative ? -$result : $result;
}

private static function incrementDigitString(string $digits): string
{
    $index = strlen($digits) - 1;
    while ($index >= 0) {
        if ($digits[$index] === '9') {
            $digits[$index] = '0';
            --$index;
        } else {
            $digits[$index] = (string) ((int) $digits[$index] + 1);

            return $digits;
        }
    }

    return '1' . $digits;
}

